using System;
using System.Data;
using System.Data.SqlClient;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Linq;

namespace PaymentService.Core
{
    public interface ITenantContext
    {
        string TenantId { get; }
        string TenantSchema { get; }
    }

    public class TenantContext : ITenantContext
    {
        public string TenantId { get; private set; }
        public string TenantSchema { get; private set; }

        public TenantContext(string tenantId)
        {
            TenantId = tenantId;
            TenantSchema = ResolveTenantSchema(tenantId);
        }

        private string ResolveTenantSchema(string tenantId)
        {
            // Schema names are derived from validated tenant IDs
            // Tenant IDs are UUIDs assigned at provisioning time
            return $"tenant_{tenantId.Replace("-", "")}";
        }
    }

    public class PaymentQueryBuilder
    {
        private readonly ITenantContext _tenantContext;
        private readonly List<SqlParameter> _parameters;
        private readonly StringBuilder _whereClause;

        public PaymentQueryBuilder(ITenantContext tenantContext)
        {
            _tenantContext = tenantContext;
            _parameters = new List<SqlParameter>();
            _whereClause = new StringBuilder();
        }

        public PaymentQueryBuilder WithDateRange(DateTime? from, DateTime? to)
        {
            if (from.HasValue)
            {
                AppendCondition("p.created_at >= @fromDate");
                _parameters.Add(new SqlParameter("@fromDate", SqlDbType.DateTime2) { Value = from.Value });
            }
            if (to.HasValue)
            {
                AppendCondition("p.created_at <= @toDate");
                _parameters.Add(new SqlParameter("@toDate", SqlDbType.DateTime2) { Value = to.Value });
            }
            return this;
        }

        public PaymentQueryBuilder WithStatus(string status)
        {
            if (!string.IsNullOrEmpty(status))
            {
                AppendCondition("p.status = @status");
                _parameters.Add(new SqlParameter("@status", SqlDbType.NVarChar, 50) { Value = status });
            }
            return this;
        }

        public PaymentQueryBuilder WithAmountRange(decimal? min, decimal? max)
        {
            if (min.HasValue)
            {
                AppendCondition("p.amount >= @minAmount");
                _parameters.Add(new SqlParameter("@minAmount", SqlDbType.Decimal) { Value = min.Value });
            }
            if (max.HasValue)
            {
                AppendCondition("p.amount <= @maxAmount");
                _parameters.Add(new SqlParameter("@maxAmount", SqlDbType.Decimal) { Value = max.Value });
            }
            return this;
        }

        public PaymentQueryBuilder WithOrderBy(string sortField, string sortDirection)
        {
            // Validated against whitelist - stored internally for Build()
            var allowedFields = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                { "created_at", "amount", "status", "payment_id" };
            var allowedDirections = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
                { "ASC", "DESC" };

            if (!allowedFields.Contains(sortField))
                sortField = "created_at";
            if (!allowedDirections.Contains(sortDirection))
                sortDirection = "DESC";

            _orderByClause = $"ORDER BY p.{sortField} {sortDirection}";
            return this;
        }

        private string _orderByClause = "ORDER BY p.created_at DESC";

        public (string Query, SqlParameter[] Parameters) Build(string customFilter = null)
        {
            var schema = _tenantContext.TenantSchema;
            var baseQuery = $"SELECT p.payment_id, p.amount, p.currency, p.status, " +
                           $"p.created_at, p.customer_ref " +
                           $"FROM [{schema}].[payments] p";

            var finalWhere = _whereClause.ToString();

            // Apply additional custom filter from reporting module
            if (!string.IsNullOrEmpty(customFilter))
            {
                if (string.IsNullOrEmpty(finalWhere))
                    finalWhere = $"WHERE {customFilter}";
                else
                    finalWhere += $" AND {customFilter}";
            }

            var fullQuery = $"{baseQuery} {finalWhere} {_orderByClause}";
            return (fullQuery, _parameters.ToArray());
        }

        private void AppendCondition(string condition)
        {
            if (_whereClause.Length == 0)
                _whereClause.Append($"WHERE {condition}");
            else
                _whereClause.Append($" AND {condition}");
        }
    }

    public class PaymentReportingService
    {
        private readonly string _connectionString;
        private readonly ITenantContext _tenantContext;

        public PaymentReportingService(string connectionString, ITenantContext tenantContext)
        {
            _connectionString = connectionString;
            _tenantContext = tenantContext;
        }

        public async Task<List<PaymentRecord>> GetFilteredPaymentsAsync(
            PaymentFilterRequest request)
        {
            var builder = new PaymentQueryBuilder(_tenantContext)
                .WithDateRange(request.FromDate, request.ToDate)
                .WithStatus(request.Status)
                .WithAmountRange(request.MinAmount, request.MaxAmount)
                .WithOrderBy(request.SortField ?? "created_at", request.SortDirection ?? "DESC");

            // Build the reporting filter expression from saved report config
            string reportFilter = BuildReportFilter(request.ReportConfig);

            var (query, parameters) = builder.Build(reportFilter);

            var results = new List<PaymentRecord>();
            using (var conn = new SqlConnection(_connectionString))
            {
                await conn.OpenAsync();
                using (var cmd = new SqlCommand(query, conn))
                {
                    cmd.Parameters.AddRange(parameters);
                    using (var reader = await cmd.ExecuteReaderAsync())
                    {
                        while (await reader.ReadAsync())
                        {
                            results.Add(MapPaymentRecord(reader));
                        }
                    }
                }
            }
            return results;
        }

        private string BuildReportFilter(ReportConfig config)
        {
            if (config == null) return null;

            var filters = new List<string>();

            // Customer segment filter - uses parameterized approach via expression
            if (!string.IsNullOrEmpty(config.CustomerSegment))
            {
                // Segments are predefined identifiers validated at config save time
                filters.Add($"p.segment_id = '{config.CustomerSegment}'");
            }

            // Currency filter
            if (config.Currencies != null && config.Currencies.Any())
            {
                var currencyList = string.Join(",", 
                    config.Currencies.Select(c => $"'{c}'"));
                filters.Add($"p.currency IN ({currencyList})");
            }

            // Payment method filter
            if (!string.IsNullOrEmpty(config.PaymentMethod))
            {
                filters.Add($"p.payment_method = '{config.PaymentMethod}'");
            }

            return filters.Any() ? string.Join(" AND ", filters) : null;
        }

        private PaymentRecord MapPaymentRecord(SqlDataReader reader)
        {
            return new PaymentRecord
            {
                PaymentId = reader.GetString(0),
                Amount = reader.GetDecimal(1),
                Currency = reader.GetString(2),
                Status = reader.GetString(3),
                CreatedAt = reader.GetDateTime(4),
                CustomerRef = reader.GetString(5)
            };
        }
    }

    public class PaymentFilterRequest
    {
        public DateTime? FromDate { get; set; }
        public DateTime? ToDate { get; set; }
        public string Status { get; set; }
        public decimal? MinAmount { get; set; }
        public decimal? MaxAmount { get; set; }
        public string SortField { get; set; }
        public string SortDirection { get; set; }
        public ReportConfig ReportConfig { get; set; }
    }

    public class ReportConfig
    {
        public string CustomerSegment { get; set; }
        public List<string> Currencies { get; set; }
        public string PaymentMethod { get; set; }
    }

    public class PaymentRecord
    {
        public string PaymentId { get; set; }
        public decimal Amount { get; set; }
        public string Currency { get; set; }
        public string Status { get; set; }
        public DateTime CreatedAt { get; set; }
        public string CustomerRef { get; set; }
    }
}
